SELECT FROM tag_group g LEFT JOIN lora l ON l.id = g.lora_id
AND g.scope = 'lora' AND g.lora_id = #{loraId}
AND g.scope = 'global'
AND g.category = #{category}
AND g.name LIKE '%' || #{keyword} || '%'
ORDER BY g.sort_order, g.id DESC

SELECT g.name FROM tag_group g
AND g.name LIKE '%' || #{keyword} || '%'
ORDER BY CASE WHEN g.name LIKE #{keyword} || '%' THEN 0 ELSE 1 END, g.name LIMIT #{limit}

SELECT COALESCE(MAX(sort_order), 0) FROM tag_group


        AND scope = 'lora' AND lora_id = #{loraId}


        AND scope = 'global'

